//! Parity gate against the BasicSR 1.4.2 NIQE oracle:
//! `tests/goldens_niqe.tsv` holds `(path, score)` rows regenerated by
//! `tests/golden_niqe.py`. Every golden must land within `JND/1000` of
//! [`niqe::JND`]; the worst absolute delta and the worst delta in JND units
//! are printed. Rows whose oracle score is NaN — all of them sub-96px or
//! 128px ladder/KonJND images that leave fewer than two complete 96×96
//! blocks (the oracle crashes there on the <2-row covariance) — must
//! instead report `ErrorKind::TooSmall`. Paths are relative to
//! `$ZENMETRICS_NR_GOLDEN_ROOT` (default `~/tmp`).

use niqe::{JND, Niqe};
use std::io::BufRead;
use za::zenpixels::{PixelDescriptor, PixelSlice};
use za::{ErrorKind, EvalOpts, Image, NoReferenceMetric};
use zenmetrics_abstractions as za;

fn golden_root() -> std::path::PathBuf {
    std::env::var_os("ZENMETRICS_NR_GOLDEN_ROOT")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(std::env::var("HOME").unwrap()).join("tmp"))
}

fn score_path(path: &std::path::Path) -> (u32, u32, Result<f64, ErrorKind>) {
    let path = &path.display().to_string();
    let img = image::open(path)
        .unwrap_or_else(|e| panic!("decode {path}: {e}"))
        .to_rgb8();
    let (w, h) = img.dimensions();
    let slice = PixelSlice::new(&img, w, h, w as usize * 3, PixelDescriptor::RGB8_SRGB).unwrap();
    let r = match Niqe::new().evaluate_image(Image::from(slice), EvalOpts::new()) {
        Ok(eval) => Ok(eval.score()),
        Err(e) => Err(e.error().kind()),
    };
    (w, h, r)
}

#[test]
fn matches_basicsr_goldens() {
    let tsv = std::fs::File::open(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/goldens_niqe.tsv"
    ))
    .expect("goldens_niqe.tsv (regenerate with tests/golden_niqe.py)");
    let root = golden_root();
    let tol = JND * 1e-3;
    let mut n = 0usize;
    let mut n_nan = 0usize;
    let mut worst_abs = 0.0f64;
    for line in std::io::BufReader::new(tsv).lines() {
        let line = line.unwrap();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let (path, expected) = line.split_once('\t').unwrap();
        let expected: f64 = expected.parse().unwrap();
        n += 1;
        let (w, h, got) = score_path(&root.join(path));
        if expected.is_nan() {
            // An oracle-NaN golden must surface as a port error, and the
            // kind follows the geometry: fewer than two 96×96 blocks →
            // the oracle's cov/pinv crashes → TooSmall; ≥2 blocks means
            // the content itself was degenerate → Degenerate. All 12
            // current NaN rows are 64px/128px ladder images (<2 blocks).
            let kind = if (w as usize / 96) * (h as usize / 96) < 2 {
                ErrorKind::TooSmall
            } else {
                ErrorKind::Degenerate
            };
            assert_eq!(got, Err(kind), "{path}: oracle NaN row ({w}x{h})");
            n_nan += 1;
            continue;
        }
        let got = got.unwrap_or_else(|e| panic!("niqe {path}: {e:?}"));
        let d = (got - expected).abs();
        assert!(
            d <= tol,
            "{path}: expected {expected}, got {got} (|Δ|={d} > {tol} = JND/1000)"
        );
        worst_abs = worst_abs.max(d);
    }
    assert_eq!(n, 42 + 128, "goldens row count changed — regenerate");
    eprintln!(
        "niqe parity: {n} goldens ({n_nan} NaN→error), worst |Δ| = {worst_abs:.3e} absolute = {:.3e} JND",
        worst_abs / JND
    );
}
